// Normalizes raw data from RemoteOK API & WeWorkRemotely RSS
const items = $input.all();
const normalizedJobs = [];
const seenUrls = new Set();

for (const item of items) {
  const data = item.json;

  // 1. Handle RemoteOK array response
  if (Array.isArray(data)) {
    for (const job of data) {
      if (!job.position || !job.url || job.legal) continue;

      const applyUrl = job.url.startsWith('http') ? job.url : `https://remoteok.com${job.url}`;
      if (seenUrls.has(applyUrl)) continue;
      seenUrls.add(applyUrl);

      let salary = 'Not Disclosed';
      if (job.salary_min && job.salary_max) {
        salary = `$${Number(job.salary_min).toLocaleString()} - $${Number(job.salary_max).toLocaleString()}`;
      } else if (job.salary) {
        salary = job.salary;
      }

      const cleanDesc = (job.description || '')
        .replace(/<[^>]*>?/gm, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 1200);

      normalizedJobs.push({
        jobId: String(job.id || applyUrl),
        source: 'RemoteOK',
        role: job.position || 'Software Engineer',
        company: job.company || 'Confidential',
        location: job.location || 'Remote (Worldwide)',
        salary: salary,
        tags: Array.isArray(job.tags) ? job.tags.filter(t => t.length > 1) : [],
        applyUrl: applyUrl,
        description: cleanDesc,
        dateFound: new Date().toISOString().split('T')[0]
      });
    }
  }

  // 2. Handle WeWorkRemotely RSS / Object response
  if (data.rss && data.rss.channel && data.rss.channel.item) {
    const rssItems = Array.isArray(data.rss.channel.item) ? data.rss.channel.item : [data.rss.channel.item];
    for (const rJob of rssItems) {
      const applyUrl = rJob.link || rJob.guid;
      if (!applyUrl || seenUrls.has(applyUrl)) continue;
      seenUrls.add(applyUrl);

      const titleParts = (rJob.title || '').split(': ');
      const company = titleParts.length > 1 ? titleParts[0].trim() : 'WeWorkRemotely Partner';
      const role = titleParts.length > 1 ? titleParts.slice(1).join(': ').trim() : rJob.title || 'Developer';

      const cleanDesc = (rJob.description || '')
        .replace(/<[^>]*>?/gm, ' ')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 1200);

      normalizedJobs.push({
        jobId: String(applyUrl),
        source: 'WeWorkRemotely',
        role: role,
        company: company,
        location: 'Remote',
        salary: 'Competitive / Not Disclosed',
        tags: ['Remote', 'Developer', 'Engineering'],
        applyUrl: applyUrl,
        description: cleanDesc,
        dateFound: new Date().toISOString().split('T')[0]
      });
    }
  }
}

// Limit to recent 25 jobs per run to optimize LLM and rate limits
const slicedJobs = normalizedJobs.slice(0, 25);
return slicedJobs.map(job => ({ json: job }));

// Deduplicates scraped jobs against existing records in Google Sheets
const scrapedJobs = $('Parse & Standardize Job Fields').all().map(i => i.json);
let existingUrls = new Set();

try {
  const sheetRows = $('Fetch Existing Google Sheet Rows').all().map(i => i.json);
  sheetRows.forEach(row => {
    const url = row['Apply URL'] || row['applyUrl'] || row['URL'] || row['Job URL'];
    if (url) {
      existingUrls.add(url.trim().toLowerCase());
    }
  });
} catch (err) {
  // Sheet might be empty on initial setup
  existingUrls = new Set();
}

const freshJobs = scrapedJobs.filter(job => {
  if (!job.applyUrl) return false;
  const normalizedUrl = job.applyUrl.trim().toLowerCase();
  return !existingUrls.has(normalizedUrl);
});

return freshJobs.map(job => ({ json: job }));

// AI CV Matching & Scoring Algorithm (0 - 100)
// Evaluates job requirement synergy with candidate profile

const items = $input.all();
const candidateProfile = $('Set Candidate Profile & CV').first().json.candidateProfile;

const scoredJobs = items.map(item => {
  const job = item.json;
  const roleText = (job.role || '').toLowerCase();
  const descText = (job.description || '').toLowerCase();
  const tagsText = (job.tags || []).join(' ').toLowerCase();
  const fullText = `${roleText} ${tagsText} ${descText}`;

  // 1. Primary Skills Match (Weight: 40%)
  const matchedPrimary = candidateProfile.primarySkills.filter(skill => 
    fullText.includes(skill.toLowerCase())
  );
  const primaryScore = Math.min(40, (matchedPrimary.length / Math.min(candidateProfile.primarySkills.length, 6)) * 40);

  // 2. Secondary Skills Match (Weight: 20%)
  const matchedSecondary = candidateProfile.secondarySkills.filter(skill => 
    fullText.includes(skill.toLowerCase())
  );
  const secondaryScore = Math.min(20, (matchedSecondary.length / Math.min(candidateProfile.secondarySkills.length, 4)) * 20);

  // 3. Role Title Alignment (Weight: 25%)
  let roleScore = 0;
  for (const targetRole of candidateProfile.targetRoles) {
    const targetWords = targetRole.toLowerCase().split(' ');
    const matchesAllWords = targetWords.every(w => roleText.includes(w));
    if (matchesAllWords) {
      roleScore = 25;
      break;
    } else if (targetWords.some(w => roleText.includes(w))) {
      roleScore = Math.max(roleScore, 15);
    }
  }

  // 4. Remote & Experience Synergy (Weight: 15%)
  let synergyScore = 10;
  if (job.location.toLowerCase().includes('remote') || job.location.toLowerCase().includes('worldwide')) {
    synergyScore += 5;
  }

  const totalScore = Math.min(100, Math.round(primaryScore + secondaryScore + roleScore + synergyScore));
  const allMatchedSkills = [...matchedPrimary, ...matchedSecondary];

  // Determine Match Tier
  let matchTier = "Moderate Fit (50-69%)";
  let statusColor = "#eab308";
  if (totalScore >= candidateProfile.highPriorityThreshold) {
    matchTier = "🔥 High Priority Match (80-100%)";
    statusColor = "#10b981";
  } else if (totalScore >= candidateProfile.minScoreThreshold) {
    matchTier = "⚡ Good Fit (60-79%)";
    statusColor = "#06b6d4";
  } else {
    matchTier = "Low Fit (<60%)";
    statusColor = "#ef4444";
  }

  // Generate Tailored 1-Sentence Pitch
  const topSkillsPreview = allMatchedSkills.slice(0, 3).join(', ') || "Full-Stack & Cloud Architecture";
  const tailoredPitch = `Excited to apply my ${candidateProfile.experienceYears}+ years of hands-on expertise in ${topSkillsPreview} to accelerate ${job.company}'s mission on the ${job.role} team.`;

  const fitReasoning = `Matched ${allMatchedSkills.length} key competencies (${allMatchedSkills.slice(0, 4).join(', ')}). Title synergy: ${roleScore}/25 pts. Remote compatibility confirmed.`;

  return {
    json: {
      ...job,
      matchScore: totalScore,
      matchTier: matchTier,
      statusColor: statusColor,
      matchedSkills: allMatchedSkills,
      missingSkills: candidateProfile.primarySkills.filter(s => !allMatchedSkills.includes(s)).slice(0, 3),
      tailoredPitch: tailoredPitch,
      fitReasoning: fitReasoning,
      applicationStatus: "To Apply"
    }
  };
});

// Sort descending by match score
scoredJobs.sort((a, b) => b.json.matchScore - a.json.matchScore);

return scoredJobs;
